mapper.insert:
INSERT INTO workspace_invites (
    invite_key, workspace_id, inviter_id, email, name, status, expires, created, invite_status
) VALUES (
    #{inviteKey}, #{workspaceId}, #{inviterId}, #{email}, #{name}, #{status},
    TO_DATE(#{expires}, 'YYYY-MM-DD HH24:MI:SS'), SYSDATE, #{inviteStatus}
)

mapper.update:
UPDATE workspace_invites
SET accepted_member_id = #{acceptedMemberId}, accepted = SYSDATE, invite_status = #{inviteStatus}
WHERE invite_key = #{inviteKey} AND invite_status = 0 AND status = 0 AND expires > SYSDATE

mapper.select:
SELECT workspace_member_id AS workspaceMemberId, workspace_id AS workspaceId, member_id AS memberId, status, role
FROM workspace_members
WHERE workspace_id = #{workspaceId} AND member_id = #{memberId}
